 void refreshWithdrawalReadiness(TextView out){String base=baseUrl();if(out==null)return;if(base==null){out.setTextColor(MUTED);out.setText("○  SUNUCU YAPILANDIRMASI GEREKLİ");return;}out.setTextColor(ORANGE2);out.setText("●  ÇEKİM ROTASI KONTROL EDİLİYOR…");io.submit(()->{try{HttpURLConnection h=openApi(base+"/conversion/readiness");int code=h.getResponseCode();JSONObject j=new JSONObject(readApi(h,code));h.disconnect();boolean cn=j.optBoolean("changeNowConfigured",false),sg=j.optBoolean("treasurySignerConfigured",false),ex=j.optBoolean("executionEnabled",false);String msg=ex?"●  ÇEKİM ROTASI HAZIR":"○  QUOTE HAZIR  •  TRANSFER KAPISI BEKLİYOR";if(!cn)msg="○  CHANGENOW BAĞLANTISI BEKLİYOR";else if(!sg)msg="○  QUOTE HAZIR  •  İMZA SERVİSİ BEKLİYOR";final String v=msg;final int color=ex?GREEN:(cn?ORANGE2:MUTED);runOnUiThread(()->{if(out!=null){out.setTextColor(color);out.setText(v);}});}catch(Exception e){runOnUiThread(()->{if(out!=null){out.setTextColor(MUTED);out.setText("○  ÇEKİM ROTASI DOĞRULANAMADI");}});}});}
 void refreshPayoutHistory(){String base=baseUrl(),session=secureStore.get("licence_session"),worker=betaPrefs.getString("worker_id","");if(historyText==null)return;if(base==null||session==null){historyText.setTextColor(MUTED);historyText.setText("○  OTURUM GEREKLİ");return;}historyText.setTextColor(ORANGE2);historyText.setText("●  İŞLEM GEÇMİŞİ YÜKLENİYOR…");io.submit(()->{try{HttpURLConnection c=openApi(base+"/payouts");c.setRequestProperty("Authorization","License "+session);c.setRequestProperty("X-Install-Id",worker);c.setRequestProperty("X-Worker-Id",worker);int code=c.getResponseCode();JSONObject j=new JSONObject(readApi(c,code));c.disconnect();if(code==200){JSONArray a=j.optJSONArray("payouts");StringBuilder out=new StringBuilder();if(a!=null)for(int n=0;n<Math.min(5,a.length());n++){JSONObject p=a.optJSONObject(n);if(p!=null)out.append(n==0?"":"\n").append("• ").append(p.optString("amountDisplay","—")).append(" USDT_TEST — ").append(p.optString("status","—"));}String v=out.length()==0?"○  HENÜZ DOĞRULANMIŞ İŞLEM YOK":out.toString();runOnUiThread(()->{if(historyText!=null)historyText.setText(v);});}else runOnUiThread(()->historyText.setText("○  İŞLEM GEÇMİŞİ KULLANILAMIYOR"));}catch(Exception e){runOnUiThread(()->{if(historyText!=null)historyText.setText("○  BAĞLANTI KURULAMADI");});}});}
String baseUrl(){String x=betaPrefs.getString("endpoint",BuildConfig.MARSX_API_BASE_URL).trim().replaceAll("/$","");return x.matches("https://[A-Za-z0-9._:-]+")?x:null;}
 HttpURLConnection openApi(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(7000);c.setReadTimeout(7000);c.setRequestMethod("GET");c.setRequestProperty("Accept","application/json");return c;}
 String readApi(HttpURLConnection c,int code)throws Exception{InputStream in=code>=400?c.getErrorStream():c.getInputStream();if(in==null)return "{}";StringBuilder b=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)b.append(l);}return b.toString();}
 void refreshMarsxAccount(){String base=baseUrl(),session=secureStore.get("licence_session"),worker=betaPrefs.getString("worker_id","");if(balance==null)return;if(base==null||session==null){balance.setText("— MARS-X");balance.setTextColor(MUTED);return;}balance.setText("— MARS-X");balance.setTextColor(ORANGE2);io.submit(()->{try{HttpURLConnection c=openApi(base+"/account");c.setRequestProperty("Authorization","License "+session);c.setRequestProperty("X-Install-Id",worker);c.setRequestProperty("X-Worker-Id",worker);int code=c.getResponseCode();JSONObject j=new JSONObject(readApi(c,code));c.disconnect();if(code==200){String v=j.optString("availableDisplay","0.000000");runOnUiThread(()->{if(balance!=null){balance.setText(v+" MARS-X");balance.setTextColor(WHITE);}});}else runOnUiThread(()->{if(balance!=null){balance.setText("— MARS-X");balance.setTextColor(MUTED);}});}catch(Exception ignored){runOnUiThread(()->{if(balance!=null){balance.setText("— MARS-X");balance.setTextColor(MUTED);}});}});}
 void refreshReferral(TextView codeView,TextView stats){String base=baseUrl(),session=secureStore.get("auth_session"),worker=betaPrefs.getString("worker_id","");if(base==null||session==null){codeView.setText("○  GİRİŞ GEREKLİ");codeView.setTextColor(MUTED);stats.setText("Toplam davet: —\nDavet kazancı: —");return;}codeView.setText("○  DAVET BİLGİSİ GÜNCELLENİYOR…");codeView.setTextColor(ORANGE2);io.submit(()->{try{HttpURLConnection c=openApi(base+"/auth/me");c.setRequestProperty("Authorization","Bearer "+session);c.setRequestProperty("X-Install-Id",worker);int code=c.getResponseCode();JSONObject j=new JSONObject(readApi(c,code));c.disconnect();if(code==200&&j.optBoolean("ok")){JSONObject r=j.optJSONObject("referral");if(r!=null){String rc=r.optString("code","");int n=r.optInt("invitedCount",0);long units=r.optLong("rewardUnits",0);String rw=java.math.BigDecimal.valueOf(units,6).toPlainString();betaPrefs.edit().putString("referral_code",rc).putInt("referral_invited",n).putString("referral_reward",rw).apply();runOnUiThread(()->{codeView.setText(rc.isEmpty()?"○  KOD BEKLENİYOR":rc);codeView.setTextColor(rc.isEmpty()?MUTED:WHITE);stats.setText("Toplam davet: "+n+"\nDavet kazancı: "+rw+" MARS-X");});}else runOnUiThread(()->{codeView.setText("○  DAVET BİLGİSİ KULLANILAMIYOR");codeView.setTextColor(MUTED);stats.setText("Toplam davet: —\nDavet kazancı: —");});}else runOnUiThread(()->{codeView.setText("○  DAVET BİLGİSİ GÜNCELLENEMEDİ");codeView.setTextColor(MUTED);stats.setText("Toplam davet: —\nDavet kazancı: —");});}catch(Exception ignored){runOnUiThread(()->{codeView.setText("○  DAVET BİLGİSİ  •  ÇEVRİMDIŞI");codeView.setTextColor(MUTED);stats.setText("Toplam davet: —\nDavet kazancı: —");});}});}
void loadHistory(){loadSeries("hist_power",powerHistory);loadSeries("hist_temp",tempHistory);loadSeries("hist_latency",latencyHistory);loadTimeSeries("hist_power_times",powerTimes);loadTimeSeries("hist_temp_times",tempTimes);loadTimeSeries("hist_latency_times",latencyTimes);}
 void loadSeries(String key,ArrayList<Float> out){out.clear();String raw=appPrefs.getString(key,"");if(raw.isEmpty())return;for(String x:raw.split(",")){try{out.add(Float.parseFloat(x));}catch(Exception ignored){}}while(out.size()>96)out.remove(0);}
 void addSample(String key,ArrayList<Float> out,float value){if(Float.isNaN(value)||Float.isInfinite(value)||value<0)return;out.add(value);while(out.size()>96)out.remove(0);StringBuilder b=new StringBuilder();for(Float x:out){if(b.length()>0)b.append(',');b.append(x);}appPrefs.edit().putString(key,b.toString()).apply();}
 void addTimedSample(String key,String timeKey,ArrayList<Float> out,ArrayList<Long> times,float value){if(Float.isNaN(value)||Float.isInfinite(value)||value<0)return;long now=System.currentTimeMillis();out.add(value);times.add(now);while(out.size()>96)out.remove(0);while(times.size()>96)times.remove(0);StringBuilder vb=new StringBuilder(),tb=new StringBuilder();for(Float x:out){if(vb.length()>0)vb.append(',');vb.append(x);}for(Long x:times){if(tb.length()>0)tb.append(',');tb.append(x);}appPrefs.edit().putString(key,vb.toString()).putString(timeKey,tb.toString()).apply();}
 void loadTimeSeries(String key,ArrayList<Long> out){out.clear();String raw=appPrefs.getString(key,"");if(raw.isEmpty())return;for(String x:raw.split(","))try{out.add(Long.parseLong(x));}catch(Exception ignored){}while(out.size()>96)out.remove(0);}
void refreshDevice(){Intent i=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null)return;int level=i.getIntExtra(android.os.BatteryManager.EXTRA_LEVEL,-1),scale=i.getIntExtra(android.os.BatteryManager.EXTRA_SCALE,100),raw=i.getIntExtra(android.os.BatteryManager.EXTRA_TEMPERATURE,-1);int pct=scale>0?Math.round(level*100f/scale):-1;float tc=raw>=0?raw/10f:-1;if(battery!=null)battery.setText("Pil alt limiti %"+appPrefs.getInt("battery_limit",15)+"  •  Cihaz pili "+(pct<0?"—":pct+"%"));int lim=appPrefs.getInt("thermal_limit",43);if(temp!=null)temp.setText(tc<0?lim+"°C sınır":String.format(Locale.getDefault(),"%.1f°C / %d°C",tc,lim));if(tc>=0)addTimedSample("hist_temp","hist_temp_times",tempHistory,tempTimes,tc);}
 String poolAge(long ts){if(ts<=0)return "henüz doğrulanmadı";long sec=Math.max(0,(System.currentTimeMillis()-ts)/1000);if(sec<60)return "az önce";long min=sec/60;if(min<60)return min+" dk önce";long hr=min/60;if(hr<24)return hr+" sa önce";return (hr/24)+" gün önce";}
 void refreshPool(){final String addr=MARSX_POOL_ADDRESS;if(!VrscAddress.valid(addr)){if(power!=null)power.setText("— Sol/s");if(workers!=null)workers.setText("—");if(shares!=null)shares.setText("—");if(network!=null){network.setText("○  MARS-X sağlayıcı  •  Yapılandırma bekleniyor");network.setTextColor(MUTED);}return;}if(network!=null){network.setText("○  Havuz verisi  •  Güncelleniyor…");network.setTextColor(ORANGE2);}final long t0=System.currentTimeMillis();io.submit(()->{try{LuckPoolClient.Snapshot x=pool.load(addr);long ms=System.currentTimeMillis()-t0;final long verifiedAt=System.currentTimeMillis();appPrefs.edit().putLong("last_pool_success",verifiedAt).apply();runOnUiThread(()->{addTimedSample("hist_power","hist_power_times",powerHistory,powerTimes,(float)x.hashrate);addTimedSample("hist_latency","hist_latency_times",latencyHistory,latencyTimes,(float)ms);if(power!=null)power.setText(String.format(Locale.getDefault(),"%,.2f Sol/s",x.hashrate));if(workers!=null){int n=0;for(LuckPoolClient.Worker w:x.workers)if(w.online)n++;workers.setText(String.valueOf(n));}if(shares!=null)shares.setText(x.shareValue);if(network!=null)network.setText("●  Sağlayıcı bağlantısı  •  "+ms+" ms  •  doğrulandı");network.setTextColor(GREEN);});}catch(Exception e){final long last=appPrefs.getLong("last_pool_success",0);runOnUiThread(()->{if(power!=null)power.setText("— Sol/s");if(workers!=null)workers.setText("—");if(shares!=null)shares.setText("—");if(network!=null)network.setText("○  Havuz verisi  •  Çevrimdışı  •  son doğrulama "+poolAge(last));network.setTextColor(MUTED);});}});}
